  "mobile-clinic": { src: "/images/work/mobile-clinic.webp", w: 2000, h: 1333 },
  incubator: { src: "/images/work/incubator.webp", w: 2000, h: 1333 },
  "student-reading": { src: "/images/work/student-reading.webp", w: 1920, h: 1080 },
  "student-lab": { src: "/images/work/student-lab.webp", w: 1620, h: 1080 },
  "housing-site": { src: "/images/work/housing-site.webp", w: 2000, h: 1333 },
  "housing-roof": { src: "/images/work/housing-roof.webp", w: 1333, h: 2000 },
  "painted-house": { src: "/images/work/painted-house.webp", w: 2000, h: 1333 },
  "water-pier": { src: "/images/work/water-pier.webp", w: 2000, h: 1333 },
  "water-station": { src: "/images/work/water-station.webp", w: 2000, h: 1333 },
  "water-pipe": { src: "/images/work/water-pipe.webp", w: 2000, h: 1333 },
  "water-pump": { src: "/images/work/water-pump.webp", w: 2000, h: 1333 },
