  "greenhouse-harvest": { src: "/images/work/greenhouse-harvest.webp", w: 2000, h: 1333 },
  swimmer: { src: "/images/work/swimmer.webp", w: 1333, h: 2000 },
  "swimmer-medal": { src: "/images/work/swimmer-medal.webp", w: 1333, h: 2000 },
  relief: { src: "/images/work/relief.webp", w: 2000, h: 1124 },
  livestock: { src: "/images/work/livestock.webp", w: 2000, h: 1333 },
